const COUNTRY_LOOKUP = new Map(COUNTRIES.flatMap((country) => country.aliases.map((alias) => [alias.toLowerCase(), country] as const)));
export const findCountry = (id: string | undefined) => (id ? COUNTRY_LOOKUP.get(id.toLowerCase()) : undefined);
